import sys
from itertools import product

data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]
best = -1
for lab in product(range(3), repeat=n):
    groups = [[], [], []]
    for i in range(n):
        groups[lab[i]].append(a[i])
    if not all(groups):
        continue
    worst = None
    for d2 in groups[1]:
        c = min(abs(x - d2) for x in groups[0]) + min(abs(x - d2) for x in groups[2])
        if worst is None or c < worst:
            worst = c
    if worst > best:
        best = worst
print(best)

